parallel safe
set search_path = ''
set jit = off
as $$
  with pdk_m(key, scope, effect, grant_key) as (
    values
      ('jobs.read', 'global', 'allow', 'jobs.read'),
      ('platformRole.manage', 'global', 'allow', 'platformRole.manage')
  ),
  pdk_w as (
