-- with p_conditioned true, also the instances a conditioned allow reaches, minus only unconditional denies: the caller applies the row condition
create or replace function "permdock".permitted_team_ids_by_permission(p_permission text, p_conditioned boolean)
returns setof uuid
language sql
stable
security definer
cost 1000
rows 10
parallel safe
set search_path = ''
as $$
  select a.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'team') g(grant_key)
    union all
    select g.grant_key from "permdock".grant_keys(p_permission, 'team', 'conditioned-allow') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_team_ids(g.grant_key) a(id)
  except
  select d.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'team', 'deny') g(grant_key)
    except
    select g.grant_key from "permdock".grant_keys(p_permission, 'team', 'conditioned-deny') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_team_ids(g.grant_key) d(id)
$$;
revoke execute on function "permdock".permitted_team_ids_by_permission(text, boolean) from public, anon;
grant execute on function "permdock".permitted_team_ids_by_permission(text, boolean) to authenticated;

-- the same for a user the caller names; no client role may execute them
create or replace function "permdock".permdock_has_permission_for(p_user uuid, p_permission text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select exists (select 1 from "permdock".grant_keys(p_permission, 'global') g(grant_key) where "permdock".permdock_has_for(p_user, g.grant_key))
    and not exists (select 1 from "permdock".grant_keys(p_permission, 'global', 'deny') g(grant_key) where "permdock".permdock_has_for(p_user, g.grant_key))
$$;
revoke execute on function "permdock".permdock_has_permission_for(uuid, text) from public, anon, authenticated;

